package com.booksyde.mapper; import com.booksyde.dto.response.VolumeResponse; import com.booksyde.entity.VolumeEntity; public final class VolumeMapper {private VolumeMapper(){} public static VolumeResponse toResponse(VolumeEntity e){return new VolumeResponse(e.getId(),e.getMangaId(),e.getNumber(),e.getTitle(),e.getFileFormat(),e.getPageCount(),e.isPublished(),e.getCoverUrl(),e.getSourceType(),e.getSourcePath(),e.getUnitKind(),e.getCreatedAt());}}